#!/usr/bin/env python3
"""Create structured extractions for references not covered by the first sample."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def E(source: str, locator: str, note: str) -> dict:
    return {"source": source, "locator": locator, "note": note}


def Q(missing=None, warnings=None, sections=None):
    return {
        "status": "partial",
        "extraction_confidence": "medium",
        "completed_sections": sections or ["article", "catalog", "construction_workflow", "additional_information"],
        "missing_core_fields": missing or [],
        "warnings": warnings or [],
        "needs_human_review": True,
    }


def save(case: str, sid: str, obj: dict) -> None:
    path = ROOT / f"data/{case}/references/{sid}/parsed/extraction/{sid}__extraction.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


